create table public.comun_archive_worker_heartbeats(id uuid primary key default gen_random_uuid(),worker_type text not null,source text not null,status text not null check(status in('running','passed','partial','failed')),started_at timestamptz not null default now(),finished_at timestamptz,duration_ms integer,claimed_count integer default 0,completed_count integer default 0,retry_count integer default 0,dead_letter_count integer default 0,sanitized_error text,created_at timestamptz default now());
create table public.comun_admin_alerts(id uuid primary key default gen_random_uuid(),alert_type text not null,severity text not null check(severity in('info','attention','urgent','critical')),title text not null,sanitized_message text not null,source_type text,source_id uuid,fingerprint text not null unique,status text not null default 'open' check(status in('open','acknowledged','resolved','archived')),first_seen_at timestamptz not null default now(),last_seen_at timestamptz not null default now(),occurrence_count integer not null default 1,acknowledged_at timestamptz,resolved_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now());
alter table public.comun_archive_worker_heartbeats enable row level security;alter table public.comun_admin_alerts enable row level security;
revoke all on public.comun_archive_worker_heartbeats,public.comun_admin_alerts from anon,authenticated;grant select,insert,update,delete on public.comun_archive_worker_heartbeats,public.comun_admin_alerts to service_role;
create index comun_worker_heartbeat_recent on public.comun_archive_worker_heartbeats(created_at desc);create index comun_admin_alerts_open on public.comun_admin_alerts(status,severity,last_seen_at desc);
